contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public payable {
        require(caller != address(0) && newOwner != address(0), "zero address not allowed");

        address beforeOwner = c.owner();

        // Set msg.sender to the caller parameter without cheatcodes.
        // The test contract becomes the caller; if caller is this test contract,
        // msg.sender will be this test contract. Otherwise, caller is ignored
        // and the call is made directly from this test contract.
        if (caller != address(this)) {
            // For this test, the caller can only be this contract or an address
            // we cannot impersonate without cheatcodes, so we only test the actual
            // caller by making the call from this contract.
            require(caller == address(this), "only test contract can call");
        }

        bool reverted;
        bool success;
        try c.setOwner(newOwner) returns (bool s) {
            reverted = false;
            success = s;
        } catch {
            reverted = true;
            success = false;
        }

        address afterOwner = c.owner();

        // General rule: setOwner succeeds (returns true) and updates owner iff
        // msg.sender is the stored admin. Since only this test contract can be
        // msg.sender here, and it is the admin (it deployed c), the call must
        // succeed and set the owner to newOwner. If it did not, the rule is broken.
        assert(!reverted && success && afterOwner == newOwner);
    }

    receive() external payable {}
}

